package com.shopsphere;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;@Service public class CartService{private final CartRepository repo;private final ProductPricingGateway pricing;public CartService(CartRepository r,ProductPricingGateway p){repo=r;pricing=p;}public Cart get(UUID user){return repo.find(user).orElse(Cart.empty(user));}public Cart add(UUID user,UUID product,int quantity){if(quantity<=0)throw new BusinessException("Quantity must be positive");var p=pricing.get(product);List<CartItem>items=new ArrayList<>(get(user).items());int index=-1;for(int i=0;i<items.size();i++)if(items.get(i).productId().equals(product))index=i;int total=quantity;if(index>=0){total+=items.get(index).quantity();items.remove(index);}items.add(item(p,total));return save(user,items);}public Cart update(UUID user,UUID product,int quantity){if(quantity<=0)throw new BusinessException("Quantity must be positive");List<CartItem>items=new ArrayList<>(get(user).items());if(items.stream().noneMatch(i->i.productId().equals(product)))throw new NotFoundException("Cart item not found");var p=pricing.get(product);items.replaceAll(i->i.productId().equals(product)?item(p,quantity):i);return save(user,items);}public Cart remove(UUID user,UUID product){List<CartItem>items=new ArrayList<>(get(user).items());if(!items.removeIf(i->i.productId().equals(product)))throw new NotFoundException("Cart item not found");return save(user,items);}public void clear(UUID user){repo.delete(user);}private CartItem item(ProductPricingGateway.Snapshot p,int q){return new CartItem(p.productId(),p.name(),p.imageUrl(),p.currentPrice(),q,p.currentPrice().multiply(BigDecimal.valueOf(q)));}private Cart save(UUID u,List<CartItem>i){BigDecimal sub=i.stream().map(CartItem::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add);return repo.save(new Cart(u,List.copyOf(i),sub,i.stream().mapToInt(CartItem::quantity).sum(),Instant.now()));}}
